def prune_messages(
    messages: list[dict[str, Any]],
    context_window_tokens: int,
    *,
    soft_ratio: float | None = None,
    keep_recent: int | None = None,
    max_chars: int | None = None,
    hard_max_total_chars: int | None = None,
) -> list[dict[str, Any]]:
    """Prune old tool-result messages to fit within the context window.

    Returns a new list (shallow copy) with pruned messages. User/assistant messages
    are never modified. Only tool results before the last ``keep_recent`` assistant
    turns are pruned by substituting large outputs with a single generic summary line.

    If ``hard_max_total_chars`` is set and the total still exceeds it after soft
    pruning, a second pass force-prunes the oldest tool results (regardless of
    ``keep_recent``) until the total is under the hard cap.
    """
    try:
        from nanobot.groupchat.history import history_settings as hs
        if soft_ratio is None:
            soft_ratio = hs.pruning_soft_ratio()
        if keep_recent is None:
            keep_recent = hs.pruning_keep_recent()
        if max_chars is None:
            max_chars = hs.pruning_soft_max_chars()
        if hard_max_total_chars is None:
            hard_max_total_chars = hs.pruning_hard_max_total_chars()
    except Exception:
        pass

    if soft_ratio is None:
        soft_ratio = DEFAULT_SOFT_RATIO
    if keep_recent is None:
        keep_recent = DEFAULT_KEEP_RECENT
    if max_chars is None:
        max_chars = DEFAULT_MAX_CHARS

    if not messages or context_window_tokens <= 0:
        return messages

    char_window = context_window_tokens * CHARS_PER_TOKEN
    total_chars = _estimate_total_chars(messages)
    ratio = total_chars / char_window

    # ── Phase 1: Soft pruning (triggered by soft_ratio) ──
    if ratio >= soft_ratio:
        cutoff = _find_cutoff_index(messages, keep_recent)
        if cutoff > 0:
            prunable: list[int] = []
            for i in range(cutoff):
                if messages[i].get("role") == "tool":
                    content = messages[i].get("content", "")
                    if isinstance(content, str) and len(content) > max_chars:
                        prunable.append(i)

            if prunable:
                result = list(messages)
                tool_map = _build_tool_map(messages)

                for i in prunable:
                    content = result[i].get("content", "")
                    if not isinstance(content, str) or len(content) <= max_chars:
                        continue

                    tcid = result[i].get("tool_call_id", "")
                    tool_name, tool_args = tool_map.get(tcid, ("unknown_tool", ""))

                    summary = _summarize_tool_result(tool_name, tool_args, content)
                    result[i] = {**result[i], "content": summary}

                total_chars = _estimate_total_chars(result)
            else:
                result = list(messages)
        else:
            result = list(messages)
    else:
        result = list(messages)

    # ── Phase 2: Hard cap enforcement (guaranteed ceiling) ──
    # If total still exceeds hard_max_total_chars, force-prune oldest tool results
    # regardless of keep_recent, until under the limit.
    # This is a safety net — should rarely trigger in normal operation.
    if hard_max_total_chars and hard_max_total_chars > 0 and total_chars > hard_max_total_chars:
        tool_map = _build_tool_map(messages)
        # Collect all tool message indices sorted oldest-first
        tool_indices = [i for i, m in enumerate(result) if m.get("role") == "tool"]

        for i in tool_indices:
            content = result[i].get("content", "")
            if not isinstance(content, str):
                continue
            tcid = result[i].get("tool_call_id", "")
            tool_name, tool_args = tool_map.get(tcid, ("unknown_tool", ""))
            summary = _summarize_tool_result(tool_name, tool_args, content)
            if len(summary) < len(content):
                result[i] = {**result[i], "content": summary}
            if _estimate_total_chars(result) <= hard_max_total_chars:
                break

    return result

